import{_ as e,o as s,c as a,a2 as r}from"./chunks/framework.C8nVztS1.js";const c=JSON.parse('{"title":"Why untestutils","description":"Live targets vs stubs, shared prepare for CI speed, and how this differs from helpers or @nuxt/test-utils.","frontmatter":{"title":"Why untestutils","description":"Live targets vs stubs, shared prepare for CI speed, and how this differs from helpers or @nuxt/test-utils.","outline":"deep"},"headers":[],"relativePath":"why.md","filePath":"why.md","lastUpdated":1790051782000}'),i={name:"why.md"};function o(n,t,l,d,h,p){return s(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="why-untestutils" tabindex="-1">Why untestutils <a class="header-anchor" href="#why-untestutils" aria-label="Permalink to &quot;Why untestutils&quot;">​</a></h1><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Shipping software is not “a component in happy-dom”. It is a <strong>built</strong> app, a <strong>running</strong> process on a real URL, and side effects that only appear after prepare/start (i18n merges, cookies, sitemap, Nitro routes, …).</p><p>If the suite never walks that path, you test a parallel universe. Failures show up in staging instead.</p><p>Most “test utils” help you write <em>more</em> tests. untestutils changes <em>what</em> you test: the same prepare → start → URL path users hit — shared across Vitest and Playwright.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Recipe  →  prepare?  →  start  →  { url } and/or { dir }</span></span>\n<span class="line"><span>Harness →  useHarness(&#39;id&#39;)  /  Playwright test.use({ harness })</span></span></code></pre></div><p>You describe <strong>how the real target comes up</strong>. Specs assert against that live target.</p><h2 id="speed-ci" tabindex="-1">Speed (CI) <a class="header-anchor" href="#speed-ci" aria-label="Permalink to &quot;Speed (CI)&quot;">​</a></h2><p>“Test like production” only works if prepare is not paid on every file.</p><table tabindex="0"><thead><tr><th>Approach</th><th>Cost</th></tr></thead><tbody><tr><td>Rebuild / remock per file</td><td>Slow; CI scales with file count</td></tr><tr><td><strong>Shared prepare</strong> (identity hash → <code>.untestutils/builds</code>)</td><td>Prepare once, many specs / workers reuse</td></tr></tbody></table><p>That is the main time win vs per-file setup (including typical <code>@nuxt/test-utils</code> e2e patterns). Cache <code>.untestutils/</code> in CI when inputs are stable; use <code>prewarm</code> so cold start is not on the first test alone.</p><p>This is <strong>not</strong> “faster than Vitest/Playwright” — those are runners. untestutils makes <em>live</em> e2e affordable.</p><h2 id="vs-usual-helpers" tabindex="-1">Vs usual helpers <a class="header-anchor" href="#vs-usual-helpers" aria-label="Permalink to &quot;Vs usual helpers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Usual</th><th>untestutils</th></tr></thead><tbody><tr><td>Restart / remock the app per file</td><td>One prepare, many files</td></tr><tr><td>Framework APIs that hide the URL</td><td>Same recipe ids in Vitest <strong>and</strong> Playwright</td></tr><tr><td>Assert on stubs only</td><td>Assert on live <code>$fetch</code>, <code>page</code>, SEO, cookies, redirects</td></tr><tr><td>Hand-rolled <code>globalSetup</code> / <code>webServer</code></td><td>Drivers (<code>nuxt</code>, <code>staticDir</code>, <code>command</code>, <code>host</code>, …)</td></tr></tbody></table><p>Utils (<code>untestutils/utils</code>) help with <strong>real-runtime</strong> checks — they are not a second testing philosophy.</p><h2 id="vs-nuxt-test-utils" tabindex="-1">Vs <code>@nuxt/test-utils</code> <a class="header-anchor" href="#vs-nuxt-test-utils" aria-label="Permalink to &quot;Vs `@nuxt/test-utils`&quot;">​</a></h2><p>Clean break, not a drop-in. Keep Vitest/Playwright skills; change how apps are prepared and shared. See <a href="/untestutils/migration/from-nuxt-test-utils">Migrate from @nuxt/test-utils</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/untestutils/guide/demo">Demo — mass Nuxt e2e</a> — ~200 live assertions, one shared prepare</li><li><a href="/untestutils/community-pain-points">Community pain points</a> — upstream issues we designed against</li><li><a href="/untestutils/guide/getting-started">Getting started</a></li><li><a href="/untestutils/guide/how-it-works">How it works</a></li><li><a href="/untestutils/roadmap">Roadmap</a> — path to 1.0</li></ul>',20)])])}const m=e(i,[["render",o]]);export{c as __pageData,m as default};
